// stream-lab.mjs —— 可直接运行：node stream-lab.mjs
// 演示：异步生成器数据源 -> objectMode 转换 -> 慢消费者，并正确处理背压与取消
import { Readable, Transform, Writable } from 'node:stream';
import { pipeline } from 'node:stream/promises';
import { setTimeout as sleep } from 'node:timers/promises';

// ① 数据源：异步生成器可被 Readable.from 直接消费
async function* dataSource(total) {
  for (let i = 0; i < total; i++) {
    await sleep(15); // 模拟慢速 I/O（比如查库）
    yield { id: i, payload: `record-${i}`.padEnd(40, '*') };
  }
}

// ② 转换流：objectMode 读入对象，输出 Buffer 字符串行
const toJsonLine = new Transform({
  objectMode: true, // 读取端按「对象」计数
  transform(record, _enc, cb) {
    this.push(JSON.stringify(record) + '\n');
    cb(); // 必须调用，否则流水线卡住
  },
});

// ③ 慢消费者：highWaterMark 很小，很快触发背压
const slowSink = new Writable({
  highWaterMark: 2,
  write(chunk, _enc, cb) {
    setTimeout(() => {
      console.log('写出:', chunk.toString().trim().slice(0, 30));
      cb();
    }, 25);
  },
});

// ④ 用 pipeline 串联：错误自动传播 + 自动销毁 + 支持 AbortSignal
const ac = new AbortController();
setTimeout(() => ac.abort(), 5000); // 5 秒后取消，模拟超时场景

try {
  await pipeline(
    Readable.from(dataSource(20)),
    toJsonLine,
    slowSink,
    { signal: ac.signal }
  );
  console.log('流水线完成 ✅');
} catch (err) {
  console.error('流水线中断:', err.name, '-', err.message);
}

// ⑤ 手动演示背压信号：write() 的返回值
const probe = new Writable({
  highWaterMark: 5,
  write(_chunk, _enc, cb) { setTimeout(cb, 10); },
});
console.log('第一次 write 返回:', probe.write('1234')); // 缓冲 4 < 5
console.log('第二次 write 返回:', probe.write('5678')); // 缓冲 8 >= 5
probe.on('drain', () => console.log('drain：缓冲已清空，可以继续写'));

